css:
#template-launcher {
  position: fixed;
  bottom: 18px;
  left: 18px;
  z-index: 9999;
  background: var(--bg-alt);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 12px;
  width: 260px;
  box-shadow: 0 8px 20px rgba(0,0,0,0.16);
}
#template-launcher h4 {
  margin: 0 0 8px 0;
  font-size: 1rem;
}
#template-launcher .template-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 6px 0;
}
#template-launcher button {
  flex: 1;
  background: var(--button-bg);
  color: var(--button-text);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 8px 10px;
  cursor: pointer;
}
#template-launcher .helper {
  color: var(--text-secondary);
  font-size: 0.85rem;
  margin-top: 6px;
}

js:
(function() {
  'use strict';

  const api = window.CardSpoke?.utils || window.CardSpoke;
  if (!api?.createCard) {
    console.warn('Quick Templates Plugin: createCard API not available');
    return;
  }

  const templates = [
    {
      name: 'Meeting Notes',
      tag: 'meeting',
      title: 'Meeting: ',
      body: '# Agenda
- Topic

# Decisions
- 

# Action Items
- [ ] Owner:  Due:'
    },
    {
      name: 'Decision Log',
      tag: 'decision',
      title: 'Decision: ',
      body: '# Context
- 

# Options
- Option A
- Option B

# Decision
- 

# Rationale
- 

# Follow-ups
- [ ]'
    },
    {
      name: 'Bug Report',
      tag: 'bug',
      title: 'Bug: ',
      body: '# Expected

# Observed

# Steps to Reproduce
1. 
2. 

# Environment
- Browser:
- Version:

# Notes
- ' 
    }
  ];

  function buildLauncher() {
    if (document.getElementById('template-launcher')) return;
    const box = document.createElement('div');
    box.id = 'template-launcher';
    box.innerHTML = '<h4>Template Launcher</h4><div class=\

>Creates cards instantly with starter content.</div>';
    document.body.appendChild(box);

    const list = box.querySelector('.template-list');

    templates.forEach(t => {
      const row = document.createElement('div');
      row.className = 'template-row';

      const btn = document.createElement('button');
      btn.textContent = t.name;
      btn.addEventListener('click', async () => {
        btn.disabled = true;
        btn.textContent = 'Creating...';
        try {
          const card = await api.createCard({ title: t.title, body: t.body, tags: [t.tag, 'template'] });
          api?.showToast?.(`${t.name} created`, 'success');
          if (card?.id) {
            api?.addTag?.(card.id, 'new');
          }
        } catch (err) {
          console.error('Template creation failed', err);
          api?.showToast?.('Could not create card', 'error');
        } finally {
          btn.disabled = false;
          btn.textContent = t.name;
        }
      });

      row.appendChild(btn);
      list.appendChild(row);
    });
  }

  buildLauncher();
})();
